import 'dart:typed_data';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../domain/business_records.dart';

class BusinessCenterRepository {
 BusinessCenterRepository({SupabaseClient? client}):_db=client??Supabase.instance.client;
 final SupabaseClient _db;
 String get _actorId=>_db.auth.currentUser?.id??(throw StateError('Please sign in again.'));
 Future<String> _employeeId() async {final row=await _db.from('users').select('id').eq('auth_user_id',_actorId).single();return row['id'].toString();}
 Future<List<DialogReport>> dialogReports({String? type,bool archive=false}) async {var q=_db.from('dialog_reports').select('*');q=archive?q.not('archived_at','is',null):q.isFilter('archived_at',null).isFilter('deleted_at',null);if(type!=null)q=q.eq('report_type',type);final rows=await q.order('period_start',ascending:false);return rows.map((e)=>DialogReport.fromJson(Map<String,dynamic>.from(e))).toList();}
 Future<DialogReport> uploadDialogReport({required String title,required String type,required DateTime start,required DateTime end,required String fileName,required Uint8List bytes}) async {if(type!='weekly'&&type!='monthly')throw const FormatException('Choose weekly or monthly report.');if(end.isBefore(start))throw const FormatException('Report end date must be on or after start date.');if(bytes.isEmpty||bytes.length>25*1024*1024)throw const FormatException('Report must be between 1 byte and 25 MB.');final mime=reportMimeType(fileName);final id=DateTime.now().microsecondsSinceEpoch.toString();final safe=fileName.replaceAll(RegExp(r'[^A-Za-z0-9._-]'),'_');final path='reports/${DateTime.now().year}/$id_$safe';await _db.storage.from('dialog-reports').uploadBinary(path,bytes,fileOptions:FileOptions(contentType:mime,upsert:false));try{final row=await _db.from('dialog_reports').insert({'report_type':type,'title':title.trim(),'period_start':start.toIso8601String().substring(0,10),'period_end':end.toIso8601String().substring(0,10),'file_path':path,'file_name':fileName,'mime_type':mime,'file_size_bytes':bytes.length,'uploaded_by':await _employeeId()}).select().single();return DialogReport.fromJson(Map<String,dynamic>.from(row));}catch(_){await _db.storage.from('dialog-reports').remove([path]);rethrow;}}
 Future<String> downloadDialogReport(DialogReport report) async {final url=await _db.storage.from('dialog-reports').createSignedUrl(report.filePath,300);await _db.from('report_downloads').insert({'report_id':report.id,'downloaded_by':await _employeeId(),'file_name':report.fileName});return url;}
 Future<void> archiveDialogReport(DialogReport r) async {final actor=await _employeeId();await _db.from('report_archive').insert({'report_id':r.id,'archived_by':actor,'reason':'Archived by Owner'});await _db.from('dialog_reports').update({'archived_at':DateTime.now().toUtc().toIso8601String(),'archived_by':actor}).eq('id',r.id);}
 Future<void> deleteDialogReport(DialogReport r) async {final actor=await _employeeId();await _db.from('dialog_reports').update({'deleted_at':DateTime.now().toUtc().toIso8601String(),'deleted_by':actor}).eq('id',r.id);await _db.storage.from('dialog-reports').remove([r.filePath]);}
 Future<List<CommissionComplaintThread>> complaints() async {final rows=await _db.from('commission_complaints').select('*,employee:users!commission_complaints_employee_id_fkey(name,agent_code)').order('created_at',ascending:false);return rows.map((e)=>CommissionComplaintThread.fromJson(Map<String,dynamic>.from(e))).toList();}
 Future<CommissionComplaintThread> submitComplaint({required String commissionId,required String type,required String message,double? expectedAmount,Uint8List? attachment,String? fileName}) async {final employee=await _employeeId();final id=DateTime.now().microsecondsSinceEpoch.toString();String? path;if(attachment!=null){if(attachment.length>10*1024*1024)throw const FormatException('Attachment must be 10 MB or smaller.');final name=(fileName??'evidence.jpg').replaceAll(RegExp(r'[^A-Za-z0-9._-]'),'_');path='$commissionId/$employee/$id_$name';await _db.storage.from('commission-evidence').uploadBinary(path,attachment,fileOptions:FileOptions(contentType:imageMimeType(name),upsert:false));}
 try{final row=await _db.from('commission_complaints').insert({'commission_id':commissionId,'employee_id':employee,'complaint_type':type,'message':message.trim(),'expected_amount':expectedAmount,'screenshot_path':path}).select().single();if(path!=null){await _db.from('complaint_attachments').insert({'complaint_id':row['id'],'uploaded_by':employee,'storage_path':path,'file_name':fileName??'evidence.jpg','mime_type':imageMimeType(fileName??'evidence.jpg'),'file_size_bytes':attachment!.length});}return CommissionComplaintThread.fromJson(Map<String,dynamic>.from(row));}catch(_){if(path!=null)await _db.storage.from('commission-evidence').remove([path]);rethrow;}}
 Future<List<Map<String,dynamic>>> complaintMessages(String id) async {final rows=await _db.from('complaint_messages').select('id,message,created_at,sender:users!complaint_messages_sender_user_id_fkey(name,agent_code)').eq('complaint_id',id).order('created_at');return rows.map((e)=>Map<String,dynamic>.from(e)).toList();}
 Future<void> addComplaintMessage(String id,String message) async {if(message.trim().isEmpty||message.trim().length>4000)throw const FormatException('Message must contain 1–4000 characters.');await _db.from('complaint_messages').insert({'complaint_id':id,'sender_user_id':await _employeeId(),'message':message.trim()});}
 Future<void> resolveComplaint(String id,{required bool reject,required String response}) async {final actor=await _employeeId();await _db.from('commission_complaints').update({'status':reject?'rejected':'resolved','owner_response':response.trim(),'resolved_by':actor,'resolved_at':DateTime.now().toUtc().toIso8601String(),'updated_at':DateTime.now().toUtc().toIso8601String()}).eq('id',id);}
 Future<List<EzCashRecord>> ezCashRecords({DateTime? month}) async {var q=_db.from('ez_cash_records').select('*,employee:users!ez_cash_records_employee_id_fkey(name,agent_code)');if(month!=null)q=q.eq('period_month',DateTime(month.year,month.month,1).toIso8601String().substring(0,10));final rows=await q.order('period_month',ascending:false).order('created_at',ascending:false);return rows.map((e)=>EzCashRecord.fromJson(Map<String,dynamic>.from(e))).toList();}
 Future<EzCashRecord> saveEzCashRecord({String? id,required String employeeId,required String? teamId,required DateTime month,required double amount,required String status,String? reference,String? last4,String? note,DateTime? paidAt}) async {if(!amount.isFinite||amount<0)throw const FormatException('Amount must be zero or greater.');if(last4!=null&&last4.isNotEmpty&&!RegExp(r'^[0-9]{4}$').hasMatch(last4))throw const FormatException('Payment number must be last four digits only.');final data={'employee_id':employeeId,'team_id':teamId,'period_month':DateTime(month.year,month.month,1).toIso8601String().substring(0,10),'amount':amount,'status':status,'payment_reference':reference?.trim(),'payment_number_last4':last4?.trim(),'owner_note':note?.trim(),'paid_at':paidAt?.toUtc().toIso8601String(),'updated_by':_actorId};final row=id==null?await _db.from('ez_cash_records').insert({...data,'created_by':_actorId}).select('*,employee:users!ez_cash_records_employee_id_fkey(name,agent_code)').single():await _db.from('ez_cash_records').update(data).eq('id',id).select('*,employee:users!ez_cash_records_employee_id_fkey(name,agent_code)').single();return EzCashRecord.fromJson(Map<String,dynamic>.from(row));}
 Future<void> deleteEzCashRecord(String id) async {await _db.from('ez_cash_records').delete().eq('id',id);}
 Future<List<Map<String,dynamic>>> employees() async {final rows=await _db.from('users').select('id,name,agent_code,team_id').eq('status','active').eq('employment_status','ACTIVE').eq('id_approval_status','APPROVED').order('name');return rows.map((e)=>Map<String,dynamic>.from(e)).toList();}
 Future<List<Map<String,dynamic>>> ezCashHistory(String id) async {final rows=await _db.from('ez_cash_history').select('id,event_type,old_record,new_record,created_at').eq('record_id',id).order('created_at',ascending:false);return rows.map((e)=>Map<String,dynamic>.from(e)).toList();}
 Future<List<Map<String,dynamic>>> ezCashReports() async {final rows=await _db.from('ez_cash_reports').select('*').isFilter('deleted_at',null).order('period_month',ascending:false);return rows.map((e)=>Map<String,dynamic>.from(e)).toList();}
 Future<String> uploadEzCashReport({required String title,required DateTime month,required String fileName,required Uint8List bytes}) async {final mime=reportMimeType(fileName);if(bytes.isEmpty||bytes.length>25*1024*1024)throw const FormatException('Report must be 1 byte–25 MB.');final path='reports/${DateTime.now().year}/${DateTime.now().microsecondsSinceEpoch}_${fileName.replaceAll(RegExp(r'[^A-Za-z0-9._-]'),'_')}';await _db.storage.from('ez-cash-reports').uploadBinary(path,bytes,fileOptions:FileOptions(contentType:mime,upsert:false));try{await _db.from('ez_cash_reports').insert({'title':title.trim(),'period_month':DateTime(month.year,month.month,1).toIso8601String().substring(0,10),'file_path':path,'file_name':fileName,'mime_type':mime,'file_size_bytes':bytes.length,'uploaded_by':await _employeeId()});return path;}catch(_){await _db.storage.from('ez-cash-reports').remove([path]);rethrow;}}
 Future<String> downloadEzCashReport(String path,String fileName) async {final row=await _db.storage.from('ez-cash-reports').createSignedUrl(path,300);return row;}
 Future<String> complaintAttachmentUrl(String path) async =>_db.storage.from('commission-evidence').createSignedUrl(path,300);
 Future<String> ezCashReportUrl(String path) async =>_db.storage.from('ez-cash-reports').createSignedUrl(path,300);
}
